@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap');

:root { --paper:#f4f5f3; --ink:#202529; --muted:#6c7376; --line:#d8dcda; --blue:#224bcc; --blue-dark:#19399c; --white:#fff; --radius:3px; --max:1440px; }
* { box-sizing:border-box; }
html { scroll-behavior:smooth; }
body { margin:0; background:var(--paper); color:var(--ink); font-family:Manrope,Arial,sans-serif; font-size:15px; line-height:1.45; }
a { color:inherit; text-decoration:none; }
button,select,input { font:inherit; }
button,a,input,select { -webkit-tap-highlight-color:transparent; }
:focus-visible { outline:3px solid var(--blue); outline-offset:3px; }
.skip-link { position:absolute; left:1rem; top:-3rem; padding:.7rem 1rem; background:var(--ink); color:var(--white); z-index:20; }
.skip-link:focus { top:1rem; }
.site-header { min-height:76px; padding:0 clamp(1rem,3vw,3.5rem); display:flex; align-items:center; justify-content:space-between; gap:2rem; border-bottom:1px solid var(--line); }
.wordmark { font-family:Manrope,Arial,sans-serif; font-size:1.25rem; font-weight:800; letter-spacing:-.08em; line-height:.8; }
.wordmark span { display:block; letter-spacing:.14em; font-size:.54rem; margin-top:.33rem; }
.nav { display:flex; gap:clamp(1rem,2.6vw,2.8rem); align-items:center; font-size:.78rem; text-transform:uppercase; letter-spacing:.11em; font-weight:700; }
.nav a { padding:.35rem 0; border-bottom:1px solid transparent; }
.nav a:hover,.nav a[aria-current=page] { border-color:var(--ink); }
.bag-link { display:flex; align-items:center; gap:.48rem; font-weight:700; }
.bag-count { display:inline-grid; place-items:center; width:1.5rem; height:1.5rem; background:var(--blue); color:var(--white); font-size:.68rem; border-radius:50%; }
.shell { width:min(var(--max),calc(100% - 2rem)); margin:auto; }
.eyebrow { display:flex; align-items:center; gap:.7rem; color:var(--blue); font-size:.68rem; font-weight:800; letter-spacing:.16em; text-transform:uppercase; }
.eyebrow::before { content:''; width:30px; height:2px; background:var(--blue); }
.display { font-family:Manrope,Arial,sans-serif; font-size:clamp(3.6rem,9.5vw,9.8rem); line-height:.84; letter-spacing:-.095em; font-weight:800; margin:1rem 0 0; max-width:10ch; }
.display em { color:var(--blue); font-style:normal; }
.button { display:inline-flex; justify-content:center; align-items:center; min-height:48px; padding:0 1.2rem; border:1px solid var(--ink); border-radius:var(--radius); background:var(--ink); color:var(--white); font-size:.76rem; letter-spacing:.08em; text-transform:uppercase; font-weight:800; cursor:pointer; transition:background .25s,transform .25s,color .25s; }
.button:hover { background:var(--blue); border-color:var(--blue); transform:translateY(-2px); }
.button.secondary { background:transparent; color:var(--ink); }
.button.secondary:hover { color:var(--white); }
.button[disabled] { cursor:not-allowed; opacity:.45; transform:none; }
.hero { display:grid; grid-template-columns:minmax(0,.78fr) minmax(0,1.22fr); min-height:min(760px,calc(100dvh - 77px)); border-bottom:1px solid var(--line); }
.hero-copy { padding:clamp(3rem,9vw,8.5rem) clamp(1rem,4vw,5rem) 4rem 0; display:flex; flex-direction:column; justify-content:space-between; }
.hero-copy p { max-width:32rem; color:var(--muted); font-size:1.08rem; margin:2rem 0; }
.hero-actions { display:flex; flex-wrap:wrap; gap:.7rem; }
.hero-media { position:relative; min-height:590px; overflow:hidden; background:#dfe3e2; }
.hero-media img,.product-image img,.story-image img { width:100%; height:100%; display:block; object-fit:cover; transition:transform .8s cubic-bezier(.2,.7,.2,1); }
.hero-media:hover img,.product-card:hover .product-image img,.story-image:hover img { transform:scale(1.045); }
.media-note { position:absolute; bottom:1rem; left:1rem; padding:.5rem .7rem; color:var(--white); background:var(--ink); font-size:.68rem; text-transform:uppercase; letter-spacing:.1em; }
.signal-bar { display:grid; grid-template-columns:repeat(3,1fr); border-bottom:1px solid var(--line); }
.signal { padding:1.15rem 0; border-right:1px solid var(--line); font-size:.72rem; text-transform:uppercase; letter-spacing:.1em; }
.signal + .signal { padding-left:1rem; }
.signal:last-child { border:0; }
.section { padding:clamp(4rem,8vw,8rem) 0; }
.section-head { display:flex; justify-content:space-between; align-items:end; gap:2rem; margin-bottom:2.7rem; }
.section-head h2 { font-family:Manrope,Arial,sans-serif; font-size:clamp(2.2rem,5vw,5rem); letter-spacing:-.075em; line-height:.9; margin:.8rem 0 0; max-width:9ch; }
.section-head p { max-width:30rem; color:var(--muted); }
.product-grid { display:grid; grid-template-columns:repeat(12,1fr); gap:1rem; }
.product-card { grid-column:span 5; min-width:0; }
.product-card:nth-child(1) { grid-column:span 7; }
.product-card:nth-child(2) { grid-column:span 5; }
.product-card:nth-child(3) { grid-column:span 5; }
.product-card:nth-child(4) { grid-column:span 7; }
.product-image { aspect-ratio:1.65/1; overflow:hidden; background:#e2e5e3; }
.product-card:nth-child(1) .product-image img { object-fit:contain; padding:1rem; }
.product-info { display:flex; justify-content:space-between; gap:.75rem; padding:1rem 0; border-bottom:1px solid var(--line); }
.product-name { font-family:Manrope,Arial,sans-serif; font-size:1.1rem; font-weight:600; letter-spacing:-.04em; }
.product-meta { color:var(--muted); font-size:.78rem; margin-top:.25rem; }
.price { white-space:nowrap; font-weight:700; }
.statement { display:grid; grid-template-columns:1fr 1fr; gap:clamp(2rem,8vw,10rem); border-top:1px solid var(--line); }
.statement h2 { font-family:Manrope,Arial,sans-serif; font-size:clamp(2.6rem,4.2vw,4.6rem); line-height:.9; letter-spacing:-.09em; margin:0; max-width:10ch; }
.statement p { max-width:30rem; color:var(--muted); font-size:1.05rem; margin:0; }
.statement p + p { margin-top:1.5rem; }
.story-image { margin-top:clamp(3rem,8vw,8rem); aspect-ratio:2.2/1; overflow:hidden; background:#dfe3e2; }
.footer { padding:2.5rem 0 1.5rem; border-top:1px solid var(--line); display:flex; justify-content:space-between; gap:1rem; align-items:flex-end; font-size:.72rem; text-transform:uppercase; letter-spacing:.1em; }
.footer .muted { color:var(--muted); }
.page-intro { padding:clamp(4rem,9vw,9rem) 0 3rem; display:flex; justify-content:space-between; gap:2rem; align-items:end; }
.page-intro h1 { font-family:Manrope,Arial,sans-serif; font-size:clamp(3.5rem,10vw,9rem); line-height:.82; letter-spacing:-.1em; font-weight:600; margin:0; max-width:8ch; }
.page-intro p { max-width:24rem; color:var(--muted); margin:0; }
.filter-row { display:flex; align-items:center; justify-content:space-between; gap:1rem; border-top:1px solid var(--line); border-bottom:1px solid var(--line); padding:1rem 0; margin-bottom:1.5rem; }
.filters { display:flex; gap:.4rem; flex-wrap:wrap; }
.filter { border:0; background:transparent; padding:.4rem .65rem; color:var(--muted); cursor:pointer; font-size:.72rem; text-transform:uppercase; letter-spacing:.1em; font-weight:700; }
.filter.active,.filter:hover { color:var(--blue); }
select { background:transparent; border:0; color:var(--ink); font-size:.72rem; text-transform:uppercase; letter-spacing:.1em; font-weight:700; cursor:pointer; }
.detail { display:grid; grid-template-columns:minmax(0,1.1fr) minmax(320px,.9fr); gap:clamp(2rem,7vw,8rem); padding:clamp(3rem,7vw,7rem) 0; }
.detail-media { display:grid; grid-template-columns:1fr 1fr; gap:1rem; align-content:start; }
.detail-media img { width:100%; aspect-ratio:3/4; object-fit:cover; background:#e2e5e3; }
.detail-media img:first-child { grid-column:span 2; aspect-ratio:1.25/1; }
.detail-copy { position:sticky; top:2rem; align-self:start; }
.detail-copy h1 { font-family:Manrope,Arial,sans-serif; font-size:clamp(3rem,7vw,7rem); line-height:.83; letter-spacing:-.1em; margin:1rem 0; }
.detail-copy .lede { color:var(--muted); max-width:34rem; }
.detail-price { font-family:Manrope,Arial,sans-serif; font-size:1.55rem; font-weight:600; margin:2rem 0; }
.spec-row { display:flex; justify-content:space-between; border-top:1px solid var(--line); padding:.8rem 0; font-size:.8rem; }
.spec-row span:last-child { color:var(--muted); }
.buy-panel { margin-top:1.5rem; padding-top:1.5rem; border-top:1px solid var(--ink); }
.option-label { display:block; font-size:.68rem; font-weight:800; text-transform:uppercase; letter-spacing:.12em; margin-bottom:.6rem; }
.variants { display:flex; gap:.5rem; margin-bottom:1.3rem; }
.variant { padding:.65rem .8rem; border:1px solid var(--line); background:transparent; cursor:pointer; font-size:.76rem; }
.variant.active,.variant:hover { border-color:var(--blue); color:var(--blue); }
.buy-row { display:grid; grid-template-columns:94px 1fr; gap:.6rem; }
.qty { display:flex; border:1px solid var(--ink); }
.qty button { border:0; background:transparent; width:30px; cursor:pointer; font-size:1.1rem; }
.qty input { width:32px; border:0; background:transparent; text-align:center; font-weight:700; }
.stock { display:flex; gap:.5rem; align-items:center; margin:1rem 0; color:#2e6255; font-size:.76rem; }
.stock::before { content:''; width:7px; height:7px; background:#2e6255; border-radius:50%; }
.bag-layout { display:grid; grid-template-columns:1.2fr .8fr; gap:clamp(2rem,7vw,8rem); padding:clamp(3rem,7vw,7rem) 0; }
.bag-layout h1 { font-family:Manrope,Arial,sans-serif; font-size:clamp(3.5rem,8vw,8rem); line-height:.82; letter-spacing:-.1em; margin:0 0 3rem; }
.bag-item { display:grid; grid-template-columns:110px 1fr auto; gap:1rem; align-items:center; padding:1rem 0; border-top:1px solid var(--line); }
.bag-item img { width:110px; aspect-ratio:1/1; object-fit:cover; background:#e2e5e3; }
.bag-item h2 { font-family:Manrope,Arial,sans-serif; font-size:1.1rem; margin:0 0 .3rem; }
.bag-controls { display:flex; align-items:center; gap:.7rem; margin-top:.6rem; }
.bag-controls input { width:4.2rem; min-height:32px; border:1px solid var(--line); background:transparent; padding:.35rem; }
.remove { border:0; background:transparent; color:var(--muted); cursor:pointer; font-size:.7rem; text-decoration:underline; padding:0; }
.summary { align-self:start; padding:1.5rem; background:var(--ink); color:var(--white); border-radius:var(--radius); }
.summary h2 { font-family:Manrope,Arial,sans-serif; font-size:2rem; letter-spacing:-.06em; margin:0 0 2rem; }
.summary-row { display:flex; justify-content:space-between; padding:.75rem 0; border-top:1px solid #4a5052; font-size:.82rem; }
.summary .button { width:100%; background:var(--blue); border-color:var(--blue); margin-top:1rem; }
.summary .button:hover { background:var(--white); color:var(--ink); border-color:var(--white); }
.empty { padding:4rem 0; border-top:1px solid var(--line); color:var(--muted); }
.empty h2 { color:var(--ink); font-family:Manrope,Arial,sans-serif; font-size:2.2rem; letter-spacing:-.06em; }
.notice { display:none; margin-top:1rem; padding:.8rem; background:#dce8ff; color:#19399c; font-size:.78rem; }
.notice.show { display:block; }
.sr-only { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0; }
@media (max-width:800px) { .site-header { min-height:68px; gap:1rem; } .nav { gap:.8rem; font-size:.65rem; } .nav a:nth-child(2) { display:none; } .hero,.statement,.detail,.bag-layout { grid-template-columns:1fr; } .hero-copy { padding:3.5rem 0; min-height:54dvh; } .hero-media { min-height:52dvh; } .product-card,.product-card:nth-child(1),.product-card:nth-child(2),.product-card:nth-child(3),.product-card:nth-child(4) { grid-column:span 6; } .product-card:nth-child(1) .product-image,.product-card:nth-child(4) .product-image,.product-image { aspect-ratio:1/1.15; } .section-head,.page-intro { display:block; } .section-head p,.page-intro p { margin-top:1.5rem; } .detail-copy { position:static; } .bag-item { grid-template-columns:82px 1fr auto; } .bag-item img { width:82px; } }
@media (max-width:500px) { .shell { width:min(var(--max),calc(100% - 1.25rem)); } .wordmark { font-size:1.1rem; } .nav a:nth-child(2) { display:none; } .display { font-size:clamp(3.4rem,17vw,5rem); } .signal-bar { grid-template-columns:1fr; } .signal,.signal + .signal { border-right:0; border-bottom:1px solid var(--line); padding:.75rem 0; } .signal:last-child { border-bottom:0; } .product-grid { gap:.7rem; } .product-card,.product-card:nth-child(1),.product-card:nth-child(2),.product-card:nth-child(3),.product-card:nth-child(4) { grid-column:span 6; } .product-info { display:block; } .price { display:block; margin-top:.5rem; } .filter-row { align-items:flex-start; flex-direction:column; } .detail-media { gap:.6rem; } .buy-row { grid-template-columns:88px 1fr; } .footer { display:block; } .footer > * + * { margin-top:1rem; } }
@media (prefers-reduced-motion:reduce) { *,*::before,*::after { scroll-behavior:auto!important; transition-duration:.01ms!important; animation-duration:.01ms!important; animation-iteration-count:1!important; } }

const DEMO_ASSET_BASE = new URL('assets/', document.currentScript?.src || document.baseURI).href;
(function () {
  const key = 'form-earth-bag';
  const allowedVariants = ['Studio finish', 'Deep cobalt', 'Chalk interior', 'Speckled clay', 'Clear glaze', 'Ash wash', 'Raw porcelain', 'Cobalt line', 'Quiet edge'];
  const products = {
    'cobalt-vase': { name:'Cobalt Vessel 04', price:280, image:DEMO_ASSET_BASE + 'studio-vase.jpg', detail:'Wheel-thrown stoneware vessel with a deep cobalt glaze.', material:'Stoneware, cobalt glaze', dimensions:'28 × 12 cm', variants:['Deep cobalt','Chalk interior'], stock:'Available in this demo' },
    'slab-bowl': { name:'Slab Bowl 02', price:145, image:DEMO_ASSET_BASE + 'studio-bowl.jpg', detail:'Hand-built serving bowl with a softly folded rim.', material:'Speckled stoneware', dimensions:'22 × 6 cm', variants:['Speckled clay','Clear glaze'], stock:'Available in this demo' },
    'ash-cup': { name:'Ash Cup 01', price:68, image:DEMO_ASSET_BASE + 'studio-cup.jpg', detail:'A handleless drinking cup with a deep cobalt glaze and an unglazed foot.', material:'Stoneware, cobalt glaze', dimensions:'8 × 8 cm', variants:['Ash wash','Raw porcelain'], stock:'Low studio quantity' },
    'signal-plate': { name:'Signal Plate 03', price:96, image:DEMO_ASSET_BASE + 'studio-hero.jpg', detail:'A broad, low plate with a gently irregular rim and speckled chalk glaze.', material:'Speckled white stoneware', dimensions:'24 × 2 cm', variants:['Cobalt line','Quiet edge'], stock:'Available in this demo' }
  };
  const image = DEMO_ASSET_BASE + 'studio-hero.jpg';
  const valid = value => typeof value === 'string' && allowedVariants.includes(value) ? value : 'Studio finish';
  const clean = raw => { if (!Array.isArray(raw)) return []; return raw.filter(item => item && products[item.id]).map(item => ({ id:item.id, variant:valid(item.variant), qty:Math.max(1, Math.min(20, Math.floor(Number(item.qty) || 1))) })); };
  let storageUnavailable = false;
  const readBag = () => { try { return clean(JSON.parse(localStorage.getItem(key) || '[]')); } catch (_) { storageUnavailable = true; return []; } };
  const saveBag = bag => { try { localStorage.setItem(key, JSON.stringify(clean(bag))); storageUnavailable = false; } catch (_) { storageUnavailable = true; } updateCount(); showStorageError(); };
  const showStorageError = () => { document.querySelectorAll('[data-storage-error]').forEach(el => { el.hidden = !storageUnavailable; }); };
  const updateCount = () => { const n = readBag().reduce((sum, item) => sum + item.qty, 0); document.querySelectorAll('[data-bag-count]').forEach(el => el.textContent = n); };
  const add = (id, qty, variant) => { if (!products[id]) return; const bag = readBag(); const cleanVariant = valid(variant); const found = bag.find(item => item.id === id && item.variant === cleanVariant); if (found) found.qty = Math.min(20, found.qty + qty); else bag.push({ id, qty:Math.min(20, Math.max(1, qty)), variant:cleanVariant }); saveBag(bag); };
  const renderBag = () => { const host = document.querySelector('[data-bag-items]'); if (!host) return; const bag = readBag(); const empty = document.querySelector('[data-empty]'); const summary = document.querySelector('[data-summary]'); host.replaceChildren(); if (!bag.length) { empty.hidden = false; summary.hidden = true; showStorageError(); return; } empty.hidden = true; summary.hidden = false; bag.forEach(item => { const p = products[item.id]; const article = document.createElement('article'); article.className = 'bag-item'; const img = document.createElement('img'); img.src = p.image; img.alt = `${p.name} studio image`; const body = document.createElement('div'); const title = document.createElement('h2'); title.textContent = p.name; const meta = document.createElement('div'); meta.className = 'product-meta'; meta.textContent = `${item.variant} · ${p.material}`; const controls = document.createElement('div'); controls.className = 'bag-controls'; const qty = document.createElement('input'); qty.type = 'number'; qty.min = '1'; qty.max = '20'; qty.value = item.qty; qty.setAttribute('aria-label', `Quantity for ${p.name}`); qty.addEventListener('change', () => { const next = readBag(); const found = next.find(row => row.id === item.id && row.variant === item.variant); if (found) found.qty = Math.max(1, Math.min(20, Math.floor(Number(qty.value) || 1))); saveBag(next); renderBag(); }); const remove = document.createElement('button'); remove.className = 'remove'; remove.type = 'button'; remove.textContent = 'Remove'; remove.addEventListener('click', () => { saveBag(readBag().filter(row => !(row.id === item.id && row.variant === item.variant))); renderBag(); }); controls.append(qty, remove); body.append(title, meta, controls); const amount = document.createElement('strong'); amount.textContent = `€${(p.price * item.qty).toLocaleString('en-IE')}`; article.append(img, body, amount); host.append(article); }); const total = bag.reduce((sum, item) => sum + products[item.id].price * item.qty, 0); document.querySelector('[data-subtotal]').textContent = `€${total.toLocaleString('en-IE')}`; document.querySelector('[data-total]').textContent = `€${total.toLocaleString('en-IE')}`; showStorageError(); };
  const hydrateObject = () => { const title = document.querySelector('.detail-copy h1'); if (!title) return; const id = new URLSearchParams(location.search).get('item') || 'cobalt-vase'; const p = products[id] || products['cobalt-vase']; document.title = `${p.name} | FORM / EARTH`; title.textContent = p.name; document.querySelector('.detail-price').textContent = `€${p.price}`; document.querySelector('.lede').textContent = p.detail; const specs = document.querySelectorAll('.spec-row span:last-child'); specs[0].textContent = p.dimensions; specs[1].textContent = p.material; document.querySelectorAll('.detail-media img').forEach(img => { img.src = p.image || image; img.alt = `${p.name} studio image`; }); document.querySelectorAll('[data-variant]').forEach((button, index) => { button.textContent = p.variants[index] || p.variants[0]; button.setAttribute('aria-pressed', index === 0 ? 'true' : 'false'); button.classList.toggle('active', index === 0); }); const stock = document.querySelector('.stock'); if (stock) stock.textContent = p.stock; const addButton = document.querySelector('[data-add]'); if (addButton) addButton.dataset.add = id; };
  const wire = () => { hydrateObject(); updateCount(); renderBag(); document.querySelectorAll('[data-add]').forEach(btn => btn.addEventListener('click', () => { const qty = Math.max(1, Math.min(20, Number(document.querySelector('[data-qty]')?.value || 1))); const variant = document.querySelector('[data-variant].active')?.textContent || 'Studio finish'; add(btn.dataset.add, qty, variant); btn.textContent = 'Added to bag'; const live = document.querySelector('[data-live]'); if (live) live.textContent = 'Added to bag'; setTimeout(() => { btn.textContent = 'Add to bag'; }, 1400); })); document.querySelectorAll('[data-variant]').forEach(btn => btn.addEventListener('click', () => { document.querySelectorAll('[data-variant]').forEach(v => { v.classList.remove('active'); v.setAttribute('aria-pressed', 'false'); }); btn.classList.add('active'); btn.setAttribute('aria-pressed', 'true'); })); document.querySelectorAll('[data-qty-step]').forEach(btn => btn.addEventListener('click', () => { const input = document.querySelector('[data-qty]'); input.value = Math.max(1, Math.min(20, Number(input.value) + Number(btn.dataset.qtyStep))); })); const checkout = document.querySelector('[data-checkout]'); if (checkout) checkout.addEventListener('click', () => { document.querySelector('[data-notice]').classList.add('show'); checkout.textContent = 'Demo checkout complete'; checkout.disabled = true; }); showStorageError(); };
  document.addEventListener('DOMContentLoaded', wire);
  window.FORM_EARTH = { products, add };
})();

@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&display=swap');

:root{--ink:#133c37;--ink-soft:#315b54;--paper:#edf2ef;--paper-deep:#dce8e3;--line:#9fbab1;--sea:#3f7778;--coral:#c77b61;--white:#f8fbf9;--serif:'Newsreader',Georgia,serif;--sans:'DM Sans',Arial,sans-serif;--measure:1400px}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:16px;line-height:1.55}
body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.22;background-image:radial-gradient(rgba(19,60,55,.13) .6px,transparent .6px);background-size:7px 7px;mix-blend-mode:multiply;z-index:-1}
a{color:inherit;text-decoration:none}
button,input,select{font:inherit;color:inherit}
button{cursor:pointer}
img{display:block;max-width:100%}
.skip-link{position:absolute;left:12px;top:-80px;background:var(--ink);color:var(--white);padding:12px 16px;z-index:20}
.skip-link:focus{top:12px}
.site-header{border-bottom:1px solid var(--line);background:rgba(237,242,239,.94);backdrop-filter:blur(8px);position:sticky;top:0;z-index:10}
.header-inner{max-width:var(--measure);margin:auto;padding:16px 28px;display:flex;align-items:center;gap:26px}
.brand{font-family:var(--serif);font-size:31px;letter-spacing:-.04em;line-height:1}
.brand span{display:block;font-family:var(--sans);font-size:9px;letter-spacing:.16em;text-transform:uppercase;margin-top:4px;font-weight:600}
.primary-nav{display:flex;gap:22px;margin-left:auto;font-size:14px}
.primary-nav a{padding:10px 0;border-bottom:1px solid transparent}
.primary-nav a:hover,.primary-nav a[aria-current=page]{border-color:var(--ink)}
.lang-switch{display:flex;border:1px solid var(--line);margin-left:6px}
.lang-switch button{background:transparent;border:0;min-width:44px;min-height:44px;font-size:12px}
